{
  "description": "Halloween color theme for the terminal: pumpkin-orange logo and accents, blood-red prompt border, bone-colored text, ghost-green success and hex-purple plan mode. Writes the theme to ~/.claude/themes/halloween.json (the only folder Claude Code reads custom themes from) and selects it. Terminal only; Claude Desktop keeps its own look. Switch back any time with /theme.",
  "theme": "custom:halloween",
  "files": {
    ".claude/themes/halloween.json": {
      "content": "{
  "name": "Halloween",
  "base": "dark",
  "overrides": {
    "claude": "#ff7518",
    "clawd_body": "#ff7518",
    "text": "#e8dfcc",
    "inactive": "#8f8597",
    "subtle": "#4a3d50",
    "suggestion": "#ff9a4d",
    "promptBorder": "#a30d0d",
    "bashBorder": "#c2410c",
    "permission": "#b48ce0",
    "planMode": "#8a5cc2",
    "autoAccept": "#ff9a4d",
    "success": "#9be564",
    "error": "#e0352b",
    "warning": "#f0a030"
  }
}
"
    }
  }
}
